<?php
declare(strict_types=1);
require_once __DIR__ . '/bootstrap.php'; admin_require_login();
$slug = isset($_GET['slug']) && is_string($_GET['slug']) ? $_GET['slug'] : '';
$post = $slug !== '' ? relet_get_post($slug, false) : null;
if ($slug !== '' && $post === null) { http_response_code(404); admin_error_page('Post not found', 'The requested post does not exist.'); }
$post = $post ?: ['title'=>'','slug'=>'','excerpt'=>'','content'=>'','meta_title'=>'','meta_description'=>'','feature_image_url'=>'','feature_image_alt'=>'','publish_date'=>date('Y-m-d'),'status'=>'draft'];
admin_header($slug ? 'Edit post' : 'New post'); ?><section class="panel"><p class="eyebrow">Blog editor</p><h1><?= $slug ? 'Edit post' : 'Create post' ?></h1><p>Use <code>## Heading</code> for section headings and <code>- item</code> for bullet lists. All content is safely escaped when published.</p><form method="post" action="/admin/save.php"><input type="hidden" name="csrf" value="<?= relet_escape(admin_csrf()) ?>"><input type="hidden" name="original_slug" value="<?= relet_escape($slug) ?>"><div class="form-grid"><label>Title <input type="text" name="title" maxlength="140" value="<?= relet_escape($post['title']) ?>" required></label><label>Slug <input type="text" name="slug" maxlength="100" pattern="[a-z0-9]+(?:-[a-z0-9]+)*" value="<?= relet_escape($post['slug']) ?>" placeholder="generated-from-title"></label></div><label>Excerpt <textarea name="excerpt" rows="3" maxlength="300" required><?= relet_escape($post['excerpt']) ?></textarea></label><label>Content <textarea name="content" rows="18" maxlength="50000" required><?= relet_escape($post['content']) ?></textarea></label><div class="form-grid"><label>Meta title <input type="text" name="meta_title" maxlength="70" value="<?= relet_escape($post['meta_title']) ?>" required></label><label>Meta description <textarea name="meta_description" rows="3" maxlength="170" required><?= relet_escape($post['meta_description']) ?></textarea></label><label>Feature image URL <input type="text" name="feature_image_url" value="<?= relet_escape($post['feature_image_url']) ?>" placeholder="/assets/example.webp or https://..."></label><label>Feature image alt text <input type="text" name="feature_image_alt" maxlength="180" value="<?= relet_escape($post['feature_image_alt']) ?>"></label><label>Publish date <input type="date" name="publish_date" value="<?= relet_escape($post['publish_date']) ?>" required></label><label>Status <select name="status"><option value="draft" <?= $post['status']==='draft'?'selected':'' ?>>Draft</option><option value="published" <?= $post['status']==='published'?'selected':'' ?>>Published</option></select></label></div><div class="actions"><button class="button" type="submit">Save post</button><a href="/admin/">Cancel</a></div></form></section><?php admin_footer();
